import { Schema } from "effect";
// The generated-files manifest (`.smithers/generated.json`), as a repository writes it, and what the view knows of a
// generated file.
const RelativePath = Schema.String.check(Schema.isBetweenLength(1, 1024));
/** An input of a generated file: its path, with the content hash the build saw when the manifest records one. */
export const Input = Schema.Union([RelativePath, Schema.Struct({ path: RelativePath, sha256: Schema.optional(Schema.String) })]);
/**
 * One generated file: the flow that produces it (its tag) and the flow's `source` file, its inputs, its build's cache
 * key, the output's own hash, and the run that last produced it. Anything else a generator records, such as its
 * toolchain, is kept out.
 */
export const Output = Schema.Struct({
    flow: Schema.String.check(Schema.isPattern(/^[a-z0-9][a-z0-9._/-]{0,127}$/)),
    source: Schema.optional(RelativePath),
    inputs: Schema.optional(Schema.Array(Input)),
    cacheKey: Schema.optional(Schema.String.check(Schema.isBetweenLength(1, 200))),
    sha256: Schema.optional(Schema.String),
    run: Schema.optional(Schema.String.check(Schema.isPattern(/^[A-Za-z0-9._:-]{1,200}$/))),
});
/**
 * `.smithers/generated.json`: every generated file, by its path from the folder that holds `.smithers/` (the
 * repository's root, or a project inside it), as `docs/generate` and other generators write it.
 */
export const Manifest = Schema.Struct({ version: Schema.optional(Schema.Literal(1)), outputs: Schema.Record(RelativePath, Output) });
